insert into public.user_stories (id, project_id, sprint, title, pts, prio, story, ac, closed) values
  ('US-34','p2',12,'Fusion des référentiels fournisseurs',8,'Haute','En tant que gestionnaire achats, je veux consulter une fiche fournisseur unique pour les trois filiales afin de ne plus saisir trois fois le même fournisseur.','Doublons SIRET fusionnés · Historique des trois filiales conservé',null),
  ('US-36','p2',12,'API de migration · endpoints de lecture',5,'Haute','En tant que développeur intégrateur, je veux lire les fournisseurs fusionnés via une API REST afin de alimenter les ERP des filiales.','GET /suppliers paginé · Réponse en moins de 300 ms','2026-10-01'),
  ('US-37','p2',12,'Import CSV de la filiale Sud',5,'Moyenne','En tant que administrateur MDM, je veux importer le fichier fournisseurs de la filiale Sud afin de intégrer ses 4 200 fournisseurs.','Encodages UTF-8 et Latin-1 acceptés · Rapport des rejets',null),
  ('US-38','p2',12,'Documentation de l''API de migration',3,'Basse','En tant que équipe d''intégration d''une filiale, je veux disposer d''une documentation OpenAPI afin de me connecter sans assistance.','Swagger publié · Exemples d''appels',null),
  ('US-39','p2',12,'Déploiement sur l''environnement DEV',3,'Moyenne','En tant que Product Owner, je veux tester chaque incrément sur DEV afin de valider en fin de sprint.','Pipeline automatique · Données de test chargées',null),
  ('US-35','p2',13,'Tableau de rapprochement',8,'Haute','En tant que gestionnaire achats, je veux voir les fournisseurs dont le rapprochement est incertain afin de arbitrer les fusions.','Filtres par filiale · Actions fusionner et séparer',null),
  ('US-40','p2',13,'Historique des modifications',5,'Moyenne','En tant que auditeur interne, je veux voir qui a modifié une fiche fournisseur afin de tracer les changements de RIB.','Journal horodaté · Export',null),
  ('US-41','p2',null,'Export Excel du référentiel',3,'Basse','En tant que contrôleur de gestion, je veux exporter le référentiel filtré afin de préparer mes analyses.','Export .xlsx · Colonnes au choix',null),
  ('US-42','p2',null,'Alerte de doublon à la saisie',5,'Moyenne','En tant que gestionnaire achats, je veux être alerté si je crée un doublon afin de garder un référentiel propre.','Contrôle SIRET et IBAN en temps réel',null),
  ('US-51','p4',17,'Paiement en ligne de bout en bout',13,'Haute','En tant que futur assuré, je veux payer ma première cotisation en ligne afin de activer mon contrat immédiatement.','Carte et prélèvement SEPA · 3-D Secure · Reçu par e-mail',null),
  ('US-52','p4',17,'Souscription mobile · étape 3',8,'Haute','En tant que futur assuré, je veux choisir mes garanties depuis mon téléphone afin de souscrire en moins de 10 minutes.','Sauvegarde automatique · Reprise sur un autre appareil',null),
  ('US-53','p4',17,'Refonte de l''espace assuré',13,'Moyenne','En tant que assuré, je veux retrouver mes contrats et documents afin de éviter d''appeler le service client.','Tableau de bord · Téléchargement des attestations',null),
  ('US-54','p4',17,'Conformité RGAA de l''espace assuré',8,'Moyenne','En tant que assuré malvoyant, je veux naviguer au clavier et au lecteur d''écran afin de utiliser le service en autonomie.','Score RGAA ≥ 75 % · Aucune non-conformité bloquante',null),
  ('US-55','p4',18,'Paiement fractionné en 3 fois',8,'Moyenne','En tant que assuré, je veux étaler le paiement de ma cotisation annuelle afin de mieux gérer mon budget.','Option 3x · Échéancier affiché',null),
  ('US-56','p4',null,'Notification de renouvellement',5,'Basse','En tant que assuré, je veux être prévenu avant l''échéance de mon contrat afin de éviter une rupture de garantie.','Notification à J-30 et J-7',null),
  ('US-61','p3',2,'OCR des factures fournisseurs',8,'Haute','En tant que comptable fournisseurs, je veux que les factures scannées soient lues automatiquement afin de supprimer la saisie manuelle.','Reconnaissance ≥ 95 % · Montant, date et SIRET extraits',null),
  ('US-62','p3',2,'Plan de classement · direction financière',5,'Moyenne','En tant que archiviste, je veux classer les pièces selon le plan validé afin de retrouver un document en moins de 30 secondes.','Trois niveaux · Durées de conservation appliquées',null),
  ('US-63','p3',3,'Plan de classement · direction juridique',5,'Moyenne','En tant que juriste, je veux classer les contrats par typologie afin de suivre les échéances contractuelles.','Alertes d''échéance · Métadonnées contrat',null);
